import org.apache.kafka.common.message.UpdateFeaturesRequestData;import org.apache.kafka.common.requests.UpdateFeaturesRequest; public class Duplicate {public static void main(String[] args){var c=new UpdateFeaturesRequestData.FeatureUpdateKeyCollection();System.out.println(c.add(new UpdateFeaturesRequestData.FeatureUpdateKey().setFeature("duplicate").setMaxVersionLevel((short)1)));System.out.println(c.add(new UpdateFeaturesRequestData.FeatureUpdateKey().setFeature("duplicate").setMaxVersionLevel((short)2)));var r=new UpdateFeaturesRequest(new UpdateFeaturesRequestData().setFeatureUpdates(c),(short)0);System.out.println(c.size());System.out.println(r.getFeature("duplicate").versionLevel());System.out.println(r.featureUpdates());}}